## Submitted testbench
```systemverilog
`timescale 1ns/1ps

module tb;

  // -----------------------------------------------------------------------
  // Parameters and clock generation
  // -----------------------------------------------------------------------
  localparam int CLK_PERIOD = 8;                     // 125 MHz
  localparam logic [15:0] PRESCCALE_VAL = 16'd5;      // same as baseline

  logic clk = 0;
  logic rst = 1'b1;

  // -----------------------------------------------------------------------
  // DUT‑level signals
  // -----------------------------------------------------------------------
  logic [7:0]  s_axis_tdata   = 8'd0;
  logic        s_axis_tvalid  = 1'b0;
  logic [7:0]  rxd            = 1'b1;            // UART receive line
  logic [7:0]  m_axis_tdata;
  logic        m_axis_tvalid;
  logic        m_axis_tready  = 1'b0;            // force back‑pressure (keep low)
  logic [15:0] prescale       = PRESCCALE_VAL;
  logic        rx_overrun_error;
  logic        rx_frame_error;

  // -----------------------------------------------------------------------
  // Clock generation
  // -----------------------------------------------------------------------
  initial begin
    forever #(CLK_PERIOD/2) clk = ~clk;
  end

  // -----------------------------------------------------------------------
  // Reset sequence
  // -----------------------------------------------------------------------
  initial begin
    rst = 1'b1;
    #(CLK_PERIOD*2);
    rst = 1'b0;
    #(CLK_PERIOD*2);
  end

  // -----------------------------------------------------------------------
  // Helper tasks
  // -----------------------------------------------------------------------
  task automatic wait_clks(input int n);
    repeat (n) @(negedge clk);
  endtask

  // Send a complete 8‑N‑1 frame on rxd (start‑low, data LSB‑first, stop‑high)
  task automatic send_8n1_byte(input byte unsigned b);
    int bit_delay = int'(prescale) * 8;
    // start bit
    rxd = 1'b0;
    wait_clks(bit_delay);
    // data bits
    for (int i = 0; i < 8; i++) begin
      rxd = b[i];
      wait_clks(bit_delay);
    end
    // stop bit
    rxd = 1'b1;
    wait_clks(bit_delay);
    rxd = 1'b1; // idle high
  endtask

  // Force a frame error by holding the stop bit low for an extra interval
  task automatic send_bad_frame_no_stop(input byte unsigned b);
    int bit_delay = int'(prescale) * 8;
    // start bit
    rxd = 1'b0;
    wait_clks(bit_delay);
    // data bits
    for (int i = 0; i < 8; i++) begin
      rxd = b[i];
      wait_clks(bit_delay);
    end
    // hold stop low (instead of releasing high) – this generates a frame error
    rxd = 1'b0;
    wait_clks(2*bit_delay);
    // restore idle state
    rxd = 1'b1;
    wait_clks(bit_delay);
    rxd = 1'b1;
  endtask

  // -----------------------------------------------------------------------
  // DUT instantiation
  // -----------------------------------------------------------------------
  uart dut (
    .clk          (clk),
    .rst          (rst),
    .s_axis_tdata (s_axis_tdata),
    .s_axis_tvalid(s_axis_tvalid),
    .m_axis_tdata (m_axis_tdata),
    .m_axis_tvalid(m_axis_tvalid),
    .m_axis_tready(m_axis_tready),
    .rxd          (rxd),
    .prescale     (prescale)
    // remaining ports are left unconnected – they are not needed for the cover point
  );

  // -----------------------------------------------------------------------
  // Main stimulus
  // -----------------------------------------------------------------------
  initial begin
    // -------------------------------------------------------------------
    // Timeout watchdog (in case something hangs)
    // -------------------------------------------------------------------
    #100ms;
    $display("[%0t] TIMEOUT – simulation aborted", $time);
    $finish;

    // ---------------------------------------------------------------
    // 1) Send a good frame (0x3C) – this will be captured and left pending
    // ---------------------------------------------------------------
    send_8n1_byte(8'h3C);
    // Give the DUT a few cycles to assert m_axis_tvalid
    repeat (20) @(posedge clk);

    // ---------------------------------------------------------------
    // 2) Generate a frame error while the pending word (0x3C) is still held
    // ---------------------------------------------------------------
    send_bad_frame_no_stop(8'h00);          // payload irrelevant – just forces FE
    // Allow a couple of clocks for the frame‑error pulse to be sampled
    repeat (30) @(posedge clk);

    // ---------------------------------------------------------------
    // 3) Send a second good frame (0xA5) – this will overrun the pending 0x3C
    // ---------------------------------------------------------------
    send_8n1_byte(8'hA5);
    // Wait for the overrun condition to be observed
    repeat (50) @(posedge clk);

    // ---------------------------------------------------------------
    // 4) End of test – $finish will be executed cleanly
    // ---------------------------------------------------------------
    $finish;
  end

endmodule
```

